#include <vector>
#include <unordered_map>
#include <string>
#include <algorithm>

class Solution {
    int best_overall = 0;
public:
    int maxGoodSubtreeScore(std::vector<int>& values, std::vector<std::vector<int>>& edges) {
        int n = values.size();
        best_overall = 0;
        for (int v : values) best_overall = std::max(best_overall, v);

        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        std::vector<int> node_mask(n);
        for (int i = 0; i < n; ++i) {
            std::string s = std::to_string(std::abs(values[i]));
            int m = 0;
            for (char ch : s) m |= (1 << (ch - '0'));
            node_mask[i] = m;
        }

        auto dfs = [&](auto& self, int u, int p) -> std::unordered_map<int, int> {
            std::unordered_map<int, int> dp;
            dp[node_mask[u]] = values[u];

            for (int v : adj[u]) {
                if (v == p) continue;
                auto child_dp = self(self, v, u);
                auto next_dp = dp;
                for (const auto& [m1, s1] : dp) {
                    for (const auto& [m2, s2] : child_dp) {
                        if ((m1 & m2) == 0) {
                            int comb_mask = m1 | m2;
                            int comb_sum = s1 + s2;
                            if (next_dp.find(comb_mask) == next_dp.end() || comb_sum > next_dp[comb_mask]) {
                                next_dp[comb_mask] = comb_sum;
                                best_overall = std::max(best_overall, comb_sum);
                            }
                        }
                    }
                }
                dp = std::move(next_dp);
            }
            return dp;
        };

        dfs(dfs, 0, -1);
        return best_overall;
    }
};

import java.util.*;

class Solution {
    private int bestOverall = 0;

    public int maxGoodSubtreeScore(int[] values, int[][] edges) {
        int n = values.length;
        bestOverall = 0;
        for (int v : values) bestOverall = Math.max(bestOverall, v);

        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }

        int[] nodeMask = new int[n];
        for (int i = 0; i < n; i++) {
            String s = String.valueOf(Math.abs(values[i]));
            int m = 0;
            for (int j = 0; j < s.length(); j++) {
                m |= (1 << (s.charAt(j) - '0'));
            }
            nodeMask[i] = m;
        }

        dfs(0, -1, adj, nodeMask, values);
        return bestOverall;
    }

    private Map<Integer, Integer> dfs(int u, int p, List<List<Integer>> adj, int[] nodeMask, int[] values) {
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(nodeMask[u], values[u]);

        for (int v : adj.get(u)) {
            if (v == p) continue;
            Map<Integer, Integer> childDp = dfs(v, u, adj, nodeMask, values);
            Map<Integer, Integer> nextDp = new HashMap<>(dp);
            for (var e1 : dp.entrySet()) {
                int m1 = e1.getKey(), s1 = e1.getValue();
                for (var e2 : childDp.entrySet()) {
                    int m2 = e2.getKey(), s2 = e2.getValue();
                    if ((m1 & m2) == 0) {
                        int combMask = m1 | m2;
                        int combSum = s1 + s2;
                        if (!nextDp.containsKey(combMask) || combSum > nextDp.get(combMask)) {
                            nextDp.put(combMask, combSum);
                            bestOverall = Math.max(bestOverall, combSum);
                        }
                    }
                }
            }
            dp = nextDp;
        }
        return dp;
    }
}

