var maxGoodSubtreeScore = function(values, edges) {
    const n = values.length;
    let bestOverall = 0;
    for (const v of values) {
        if (v > bestOverall) bestOverall = v;
    }

    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const nodeMask = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        const s = String(Math.abs(values[i]));
        let m = 0;
        for (let j = 0; j < s.length; j++) {
            m |= (1 << (s.charCodeAt(j) - 48));
        }
        nodeMask[i] = m;
    }

    const dfs = (u, p) => {
        let dp = new Map();
        dp.set(nodeMask[u], values[u]);

        for (const v of adj[u]) {
            if (v === p) continue;
            const childDp = dfs(v, u);
            const nextDp = new Map(dp);
            for (const [m1, s1] of dp) {
                for (const [m2, s2] of childDp) {
                    if ((m1 & m2) === 0) {
                        const combMask = m1 | m2;
                        const combSum = s1 + s2;
                        if (!nextDp.has(combMask) || combSum > nextDp.get(combMask)) {
                            nextDp.set(combMask, combSum);
                            if (combSum > bestOverall) bestOverall = combSum;
                        }
                    }
                }
            }
            dp = nextDp;
        }
        return dp;
    };

    dfs(0, -1);
    return bestOverall;
};
